    "éclate en 2 projectiles vers d'autres ennemis, la balle revient vers sa planète en touchant tout sur son passage et chance de coup critique (+{critBonus}% de dégâts critiques)": "爆裂成 2 枚飞弹射向其他敌人，子弹飞回所属星球，沿途击中一切，有几率暴击（暴击伤害 +{critBonus}%）",
    "éclate en 2 projectiles vers d'autres ennemis, la balle revient vers sa planète en touchant tout sur son passage et ralentit les ennemis autour de l'impact": "爆裂成 2 枚飞弹射向其他敌人，子弹飞回所属星球，沿途击中一切，减速命中点周围的敌人",
    "éclate en 2 projectiles vers d'autres ennemis, la balle revient vers sa planète en touchant tout sur son passage et te soigne à chaque coup": "爆裂成 2 枚飞弹射向其他敌人，子弹飞回所属星球，沿途击中一切，每次命中都为你治疗",
    "éclate en 2 projectiles vers d'autres ennemis, recharge ton bouclier plus vite et la balle revient vers sa planète en touchant tout sur son passage": "爆裂成 2 枚飞弹射向其他敌人，你的护盾充能更快，子弹飞回所属星球，沿途击中一切",
