    "Ennemis coriaces : +{percent} % de vie": "坚韧的敌人：生命 +{percent}%",
    "Nuée : les ennemis arrivent {percent} % plus souvent": "蜂群：敌人出现频率提高 {percent}%",
    "Monstres en avance : les super ennemis arrivent {times} fois plus tôt": "怪物提前：超级敌人提前 {times} 倍出现",
    "Pas de régénération : ta vie ne remonte pas avec le temps": "无再生：生命不会随时间恢复",
    "Canon de verre : vie max ×{health}, dégâts ×{damage}": "玻璃大炮：最大生命 ×{health}，伤害 ×{damage}",
    "Seules les planètes tirent : toi, tu ne tires pas": "只有行星射击：你不射击",
    "🥉 tenir jusqu'à {time} · 🥈 voir {boss} arriver · 🥇 le vaincre": "🥉 坚持到 {time} · 🥈 见到 {boss} 出现 · 🥇 击败它",
    "Objectif : survivre le plus longtemps possible": "目标：尽可能久地生存",
